import React from "react";
import { Link } from "react-router-dom";
import { useCart } from "../context/CartContext";

const ProductCard = ({ product }) => {
  const { addToCart } = useCart();

  return (
    <div
      style={{
        background: "#fff",
        padding: "18px",
        borderRadius: "20px",
        boxShadow: "0 10px 25px rgba(0,0,0,0.1)",
        textAlign: "center",
        transition: "0.3s",
      }}
      onMouseOver={(e) =>
        (e.currentTarget.style.transform = "translateY(-8px)")
      }
      onMouseOut={(e) =>
        (e.currentTarget.style.transform = "translateY(0)")
      }
    >
      {/* IMAGE */}
      <img
        src={product.image}
        alt={product.name}
        style={{
          width: "100%",
          height: "220px",
          objectFit: "cover",
          borderRadius: "15px",
        }}
      />

      {/* NAME */}
      <h3 style={{ margin: "12px 0 5px", color: "#333" }}>
        {product.name}
      </h3>

      {/* PRICE + AGE */}
      <p style={{ color: "#d63384", fontWeight: "600" }}>
        ₹{product.price}
      </p>

      {product.age && (
        <p style={{ fontSize: "14px", color: "#777" }}>
          Age: {product.age}
        </p>
      )}

      {/* BUTTONS */}
      <button
        onClick={() => addToCart(product)}
        style={{
          marginTop: "10px",
          padding: "10px 18px",
          border: "none",
          borderRadius: "20px",
          background: "#ff85a2",
          color: "#fff",
          cursor: "pointer",
          width: "100%",
        }}
      >
        Add to Cart
      </button>

      <Link to={`/product/${product.id}`} style={{ textDecoration: "none" }}>
        <button
          style={{
            marginTop: "8px",
            padding: "8px 15px",
            borderRadius: "20px",
            border: "1px solid #ff85a2",
            background: "white",
            color: "#ff4f87",
            cursor: "pointer",
            width: "100%",
          }}
        >
          View Details
        </button>
      </Link>
    </div>
  );
};

export default ProductCard;
